import{_ as e,o,c as a,a2 as d}from"./chunks/framework.B0p3fmqd.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"moneywash/configuration.md","filePath":"moneywash/configuration.md","lastUpdated":1791036569000}'),i={name:"moneywash/configuration.md"};function n(r,t,s,c,h,l){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Everything you can change lives in <code>config.lua</code>. The rest of the resource is protected, and edits to protected files are lost on update.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>Config.Debug</code></td><td>Draws the target zones and prints what the script is doing. Leave <code>false</code> on a live server</td></tr><tr><td><code>Config.CheckForUpdates</code></td><td>Prints one line at startup with the latest version</td></tr><tr><td><code>Config.MinimumPolice</code></td><td>Police that must be online before a wash can start</td></tr><tr><td><code>Config.PoliceAlertChance</code></td><td>Chance that police are alerted, <code>0.90</code> is 90%</td></tr><tr><td><code>Config.PoliceJobs</code></td><td>Jobs counted as police</td></tr></tbody></table><h2 id="business" tabindex="-1">Business <a class="header-anchor" href="#business" aria-label="Permalink to &quot;Business&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>Config.BossPercentage</code></td><td>Share of washed money paid to the business owner, <code>0.10</code> is 10%</td></tr><tr><td><code>Config.BusinessSellPrice</code></td><td>Percent of the purchase price an owner gets back when selling</td></tr><tr><td><code>Config.MachineRepairCost</code></td><td>Minimum and maximum cost to repair a machine</td></tr></tbody></table><h2 id="dirty-money" tabindex="-1">Dirty money <a class="header-anchor" href="#dirty-money" aria-label="Permalink to &quot;Dirty money&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>Config.DirtyMoneyItems</code></td><td>Items accepted as dirty money</td></tr><tr><td><code>Config.UseMetadataWorth</code></td><td><code>true</code> uses an item&#39;s <code>metadata.worth</code> when it has one, so scripts that pay a whole sum in one item wash for that exact amount. <code>false</code> always uses <code>Config.BlackMoneyWorth</code></td></tr><tr><td><code>Config.BlackMoneyWorth</code></td><td>Value of an item with no <code>metadata.worth</code>. Most scripts pay one dirty money item per dollar, so keep this at <code>1</code></td></tr><tr><td><code>Config.MaxNoteWorth</code></td><td>Most a single dirty money item can wash for</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A <code>BlackMoneyWorth</code> higher than what your other scripts pay per item multiplies those payouts. Keep it at <code>1</code> unless you know how your scripts pay out dirty money.</p></div><h2 id="washing" tabindex="-1">Washing <a class="header-anchor" href="#washing" aria-label="Permalink to &quot;Washing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>Config.UseValueBasedTimer</code></td><td><code>true</code> scales the wash time with the amount washed. <code>false</code> uses a fixed time per note</td></tr><tr><td><code>Config.WashTimePerThousandMs</code></td><td>Milliseconds per $1,000 when the timer is value based</td></tr><tr><td><code>Config.WashTimePerNote</code></td><td>Seconds per note when it is not</td></tr><tr><td><code>Config.CollectTime</code></td><td>Milliseconds for the collect animation</td></tr></tbody></table><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>Config.TokenItem</code></td><td>Item name of the wash token</td></tr><tr><td><code>Config.TokenCraftingRequirements</code></td><td>Items needed to craft one token. The defaults are standard inventory items</td></tr></tbody></table>',13)])])}const f=e(i,[["render",n]]);export{m as __pageData,f as default};
